from pathlib import Path
import csv,json,shutil,statistics,subprocess
base=Path(__file__).resolve().parent;repo=base/'chronoscope-upload-local';qa=repo/'.qa/uploads';app=base/'Chronoscope Upload Lab'
raw=json.loads((qa/'native/report.json').read_text());assert raw['complete'] and all(c['complete'] for c in raw['cases'])
checks=[]
build_source=json.loads((app/'BUILD.json').read_text())['source_commit']
for name in ['upload-unit-committed','upload-paging-committed','upload-interactions-committed','upload-pixels-committed','upload-references-committed','upload-terrain-recovery-committed','upload-windows']:
 r=json.loads((qa/f'checks/{name}.json').read_text());assert r['exit_code']==0 and not r['timed_out'];checks.append(r)
 assert subprocess.run(['git','diff','--quiet',r['source_revision'],build_source,'--','frontend/src'],cwd=repo).returncode==0,'Renderer source drift between check and native binary'
rows=[]
for c in raw['cases']:
  rows.append({'dataset':c['dataset'],'variant':c['variant'],'median_worst_rebuild_frame_ms':round(statistics.median(p['frames']['max_ms'] for p in c['preparations']),2),'largest_rebuild_frame_ms':round(max(p['frames']['max_ms'] for p in c['preparations']),2),'median_total_preparation_ms':round(statistics.median(p['preparationMs'] for p in c['preparations']),2),'fps':round(sum(p['rendered_frames'] for p in c['steady'])/(sum(p['elapsed_ms'] for p in c['steady'])/1000),2),'steady_p99_ms':round(max(p['frames']['p99_ms'] for p in c['steady']),2),'steady_max_ms':round(max(p['frames']['max_ms'] for p in c['steady']),2),'steady_gaps_over_50ms':sum(p['frames']['gaps_over_50ms'] for p in c['steady']),'steady_inactive_prepared_frames':sum(p.get('inactive_prepared_frames',p.get('missing',0)) for p in c['steady']),'cpu_machine_percent':round(statistics.mean(p['resources']['cpu_total_machine_percent']['mean'] for p in c['steady']),2),'ram_private_MiB':round(statistics.mean(p['resources']['ram_private_resident_bytes']['mean'] for p in c['steady'])/1024**2,1),'gpu_3d_percent':round(statistics.mean(p['resources']['app_gpu_3d_percent']['mean'] for p in c['steady']),2),'gpu_allocated_MiB':round(statistics.mean(p['resources']['app_gpu_dedicated_bytes']['mean'] for p in c['steady'])/1024**2,1),'steady_seconds':round(sum(p['elapsed_ms'] for p in c['steady'])/1000,1),'max_upload_vertices':max(p['resident'].get('largestUploadVertices',0) for p in c['preparations']),'upload_batches':max(p['resident'].get('uploadBatches',0) for p in c['preparations'])})
  if c['variant']=='baseline':
   rows[-1]['max_upload_vertices']=None;rows[-1]['upload_batches']=None
summary={'complete':True,'method':raw['method'],'rows':rows,'checks':checks,'source_commit':json.loads((app/'BUILD.json').read_text())['source_commit'],'new_binary_sha256':json.loads((app/'BUILD.json').read_text())['binary_sha256'],'baseline_source':'4834867b0704c2376d80e29faaa22a6a2b973321','baseline_binary_sha256':raw['cases'][0]['binary_sha256'],'local_only':True,'promoted_completed_work':{'Next':'4834867b0704c2376d80e29faaa22a6a2b973321','Public':'6bcd11debd9032c1deb61abb02ea7984acbae1f9'},'correctness':'All repeated preparations accepted without missing/unready active buffers, renderer errors or early removal of the old renderer. Canceled candidates released their installed/queued primitives and retained the old drawing. Exact engine-window IDs matched before and after sustained playback. Existing interaction, framebuffer handoff, reference and terrain recovery checks passed.','limitations':['Three preparation repetitions per variant/dataset, two consecutive one-minute active navigation/playback phases per case; eight measured steady native minutes total. This is not a multi-hour endurance test.','Frame times are native WebView2 postRender cadence, not monitor presentation latency.','Preparation timings include construction, GPU readiness and frame scheduling; smaller uploads can increase total preparation time.','Paired cases isolate 100k regional and eligible global altitude tracks without basemap/terrain. Separate reference/recovery checks cover true terrain semantics.','CPU is normalized over 16 logical processors. Windows GPU allocation is attributed allocation accounting, not unique physical VRAM residency.','CPU work uses a yielding scheduler and bounded geometry pages; individual Cesium/driver operations and garbage collection still do not have a hard maximum frame time.']}
suite_paths=[]
for name in ['upload-paging-qa','resident-interactions-qa','prepared-handoff-qa','resident-reference-qa','terrain-preparation-recovery-qa']:
 candidates=sorted((repo/f'.qa/{name}').glob('*/report.json'),key=lambda p:p.stat().st_mtime,reverse=True)
 chosen=next(p for p in candidates if json.loads(p.read_text())['passed'] and json.loads((p.parent/'runtime.json').read_text())['source_revision']==build_source)
 suite_paths.append(chosen)
reports=[json.loads(p.read_text()) for p in suite_paths]
assert all(r['passed'] for r in reports)
summary['unit_tests']=175;summary['rendering_interaction_checks']=sum(len(r['checks']) for r in reports)
pixels=json.loads((suite_paths[2].parent/'pixels.json').read_text());summary['handoff_framebuffer_samples']=len(pixels['frames']);summary['handoff_swaps']=20
summary['suite_reports']=[str(p.relative_to(repo)) for p in suite_paths]
summary['retained_attempts']='Earlier GPU-only prototype and interrupted baseline stress runs remain in ignored .qa/uploads/native; final rows retain only matching binaries and completed native measurements. Baseline satellite steady playback was isolated in a fresh process after direct stress returned to the canonical path.'
dest=repo/'docs/validation/local-upload-2026-10-30';dest.mkdir(parents=True,exist_ok=True)
(dest/'report.json').write_text(json.dumps(summary,indent=2)+'\n')
with (dest/'measurements.csv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=rows[0]);w.writeheader();w.writerows(rows)
lines=['LOCAL INCREMENTAL GEOMETRY/GPU UPLOAD EXPERIMENT','', 'Full optimized Windows Chronoscope. New upload changes remain on codex/incremental-gpu-upload; they were not pushed to Next or Public. Previously completed Interaction Lab/Transition Lab changes were separately promoted to Next 4834867 / Public 6bcd11d.', '', 'Changes: split actual GPU geometry into <=8192-vertex pages, preserve overlapping timed track endpoints, warm one page between frames while retaining the previous drawing, share materials/uniforms across pages, and retain exact record/entity IDs for picking. Yield position resolution, stable entity/time/ID sorting, seam splitting and typed-array packing to input/rendering; freeze the target Time frame while preparing. Avoid repeated per-vertex temporary arrays and cache colors/positions during preparation.', '',raw['method'],'','dataset | variant | median worst rebuild frame ms | median total preparation ms | steady FPS | CPU % | private RAM MiB | app GPU 3D % | allocated GPU MiB']
for r in rows:lines.append(' | '.join(str(r[k]) for k in ['dataset','variant','median_worst_rebuild_frame_ms','median_total_preparation_ms','fps','cpu_machine_percent','ram_private_MiB','gpu_3d_percent','gpu_allocated_MiB']))
lines+=['',summary['correctness'],'','Limitations:',*summary['limitations'],'','Binary source: '+summary['source_commit'],'New binary SHA256: '+summary['new_binary_sha256'],'','Raw native intervals, screenshots and OS samples remain in .qa/uploads/native. Harness scripts were executed from the parent Windows workspace and use sibling paths/portable tools.']
(dest/'README.txt').write_text('\n'.join(lines)+'\n',encoding='utf-8')
shutil.copy2(dest/'README.txt',app/'PERFORMANCE.txt');shutil.copy2(dest/'report.json',app/'VALIDATION.json')
harness=dest/'harness';harness.mkdir(exist_ok=True)
for name in ['measure_uploads.py','upload_driver.mjs','verify_uploads.py','windows_upload_check.py','package_uploads.py','transitions_native_helpers.py','vfx_resource_gpu_counters.ps1','launch_upload_lab.py','publish_upload_results.py']:
 shutil.copy2(base/name,harness/name)
(app/'README.txt').write_text('CHRONOSCOPE UPLOAD LAB - FULL LOCAL WINDOWS APP\n\nLaunch using the included command file to use its own profile and WebView2 data. Includes the normal Chronoscope features and completed governor/import/time-rail/VFX/interactions/transition work, plus local bounded geometry/upload preparation. Use the Smooth graphics switch in Views to compare prepared and canonical rendering. See PERFORMANCE.txt for measured benefits and tradeoffs. New upload changes are local only.\n',encoding='utf-8')
print(json.dumps(rows,indent=2))
